// The question set has three layers:
//   1. FIXED questions: identity, relationship, ranking, rating, close. Never LLM-written,
//      because rankings and ratings must not depend on a model's phrasing.
//   2. Per-program FIT questions: built from a template, one per program.
//   3. The MIDDLE: generated by LLM call 1, or this DEFAULT bank when generation fails.
// "Generation is an enhancement, never a dependency."

import type { Program, Question, StudentIntake } from "./types";

const q = (
  id: string,
  section: Question["section"],
  prompt: string,
  opener: string,
  extra: Partial<Question> = {},
): Question => ({
  id,
  section,
  prompt,
  opener,
  programScope: "all",
  formMappings: [],
  source: "fixed",
  destination: "letter",
  ...extra,
});

export function firstName(intake: StudentIntake): string {
  return intake.preferredName || intake.studentName.split(" ")[0];
}

export function fixedOpening(intake: StudentIntake): Question[] {
  const n = firstName(intake);
  return [
    q("F1", "opening", "Who are you? Your name, title, organization, and role.", "I am…"),
    q(
      "F2",
      "opening",
      `How long have you known ${n}, in what capacity, and how often do you work together?`,
      `I have known ${n} since…`,
      { formMappings: ["capacity"] },
    ),
    q("F3", "opening", `In a sentence or two, why are you recommending ${n}?`, `I am recommending ${n} because…`),
  ];
}

export function fixedComparison(intake: StudentIntake): Question[] {
  const n = firstName(intake);
  return [
    q(
      "F4",
      "comparison",
      `Roughly how many students or early-career people have you supervised or taught, where does ${n} rank, and why? Only you can answer this.`,
      "Of the … I have worked with,…",
    ),
  ];
}

export function fitQuestion(intake: StudentIntake, p: Program, index: number): Question {
  const n = firstName(intake);
  return q(
    `FIT${index + 1}`,
    "fit",
    `${n} is applying to the ${p.name} at ${p.school}. Why does this program fit ${n}, and where do you see ${n} going?`,
    `This program fits ${n} because…`,
    { programScope: p.id, memoryJog: p.description },
  );
}

export function fixedClose(intake: StudentIntake): Question[] {
  const n = firstName(intake);
  const hasRating = intake.programs.some((p) => p.ratingOptions?.length);
  const out: Question[] = [
    q("F5", "close", `How strongly do you recommend ${n}, and how can the committee reach you?`, `I recommend ${n}…`),
  ];
  if (hasRating) {
    out.push(
      q("F6", "close", "If a program asks for an overall rating, which would you choose?", "(one choice)", {
        destination: "form",
        formMappings: ["rating"],
      }),
    );
  }
  out.push(
    q("F7", "close", "Anything else the committee should know?", "(anything)", {
      destination: "form",
      formMappings: ["additional"],
    }),
  );
  return out;
}

/** Generic middle questions, adapted from the original voice kit. Used when LLM call 1 fails. */
export function defaultMiddle(intake: StudentIntake): Question[] {
  const n = firstName(intake);
  const d = (id: string, section: Question["section"], prompt: string, opener: string, formMappings: string[] = [], destination: Question["destination"] = "letter") =>
    q(id, section, prompt, opener, { source: "default", formMappings, destination });
  return [
    d("D1", "context", `What is the setting where you worked with ${n}, and what makes the role demanding?`, "In this role,…"),
    d("D2", "work", `What is the main work or project you saw ${n} do, and who relies on it?`, `${n}'s main work…`),
    d("D3", "work", `What did ${n} personally build, own, or lead? Only what you know they did themselves.`, `${n}…`, ["field"]),
    d("D4", "work", `Was there a moment when the work was tested or evaluated? What happened, and what did ${n} do with the result?`, "When we…", ["effort"]),
    d("D5", "work", `What does how ${n} handled that tell you about their judgment?`, "That told me…"),
    d("D6", "leadership", "In your field, what do you think separates someone who is good from someone who is merely competent?", "I often tell people…", ["field"]),
    d("D7", "leadership", `Give one specific time ${n} showed that quality.`, "For example,…", ["group"]),
    d("D8", "leadership", `Describe a time ${n} explained something complex to people outside their specialty. What happened as a result?`, `When ${n} presented…`, ["communication"]),
    d("D9", "teamwork", `How does ${n} work with others? Any time they helped or unblocked someone without being asked?`, `On a team, ${n}…`, ["group"]),
    d("D10", "teamwork", "Tell me about a time something went wrong or got hard. How did they handle it?", "When…", ["effort", "problem"]),
    d("D11", "teamwork", `How does ${n} communicate in writing?`, `In writing, ${n}…`, ["communication"], "form"),
    d("D12", "teamwork", `What is one personal quality that stands out, and what is an example of it?`, `What stands out about ${n} is…`, ["additional"]),
  ];
}

/** Assemble the full ordered question set from a middle section (generated or default). */
export function buildQuestionSet(intake: StudentIntake, middle: Question[]): Question[] {
  return [
    ...fixedOpening(intake),
    ...middle,
    ...fixedComparison(intake),
    ...intake.programs.map((p, i) => fitQuestion(intake, p, i)),
    ...fixedClose(intake),
  ];
}
